#include <bits/stdc++.h>
#include <atcoder/modint>
using namespace std;
using namespace atcoder;

using mint = modint998244353;

#define N (int)3e+5
#define rep(i, n) for(int i = 0; i < n; ++i)

mint frac[N+1];

void pre_calc(void){
	frac[0]=mint(1);
	for(int i=1;i<=N;i++){
		frac[i]=frac[i-1]*mint(i);
	}
	return;
}

mint binom(int x,int y){
	if(x<0)return mint(0);
	if(y<0)return mint(0);
	if(y>x)return mint(0);
	return frac[x]*(frac[y].inv())*(frac[x-y].inv());
}

int main(void){
	int n;
	int l[N],r[N];
	int aok[N]={},bok[N]={};
	int m[2][2]={};
	vector<int>cand[N];
	mint ans=mint(0);
	cin>>n;
	rep(i,n){
		cin>>l[i]>>r[i];
		cand[l[i]].push_back(i);
		cand[r[i]+1].push_back(i);
		cand[n-l[i]+1].push_back(i);
		cand[n-r[i]].push_back(i);
	}
	m[0][0]=n;

	pre_calc();
	for(int i=1;i<=n-1;i++){
		int sz=cand[i].size();
		rep(j,sz){
			int z=cand[i][j];
			m[aok[z]][bok[z]]--;
			if((l[z]<=i)&&(i<=r[z]))aok[z]=1;
			else aok[z]=0;
			if((l[z]<=(n-i))&&((n-i)<=r[z]))bok[z]=1;
			else bok[z]=0;
			m[aok[z]][bok[z]]++;
		}
		if((m[0][0]==0)&&(m[1][0]<=i)&&(m[0][1]<=(n-i))){
			ans+=binom(m[1][1],i-m[1][0]);
		}
	}
	cout<<ans.val()<<endl;
}
